"""Compact view of a pulled session: per move, actor, price/terms, status, claim results, text."""
import json
import sys

full = "--full" in sys.argv
for path in [a for a in sys.argv[1:] if not a.startswith("--")]:
    d = json.load(open(path))
    r = d["result"]
    print(f"\n===== {path}  score={r.get('score'):.3f} c_open={r.get('c_open')} c_deal={r.get('c_deal')} c_best={r.get('c_best')} c_alt={r.get('c_alt')}")
    print("deal:", r.get("terms"))
    print("breakdown:", r.get("cost_breakdown"))
    bo = {}
    for b in d.get("backoffice") or []:
        bo.setdefault((b["round"], b["supplier_id"]), []).append(b["text"])
    for m in r["trace"]:
        mv = m.get("move") or {}
        terms = mv.get("terms") or {}
        sheets = mv.get("term_sheets")
        if sheets:
            terms = [s.get("terms") for s in sheets]
        print(f"\n--- r{m['round']} {m['actor']} status={mv.get('status')} terms={terms}")
        if mv.get("alternatives"):
            print("   alts:", [a.get("terms") for a in mv["alternatives"]])
        if mv.get("claim_results"):
            print("   claim_results:", [(c.get("status") or c.get("result"), c.get("refs"), c.get("reason", "")[:120]) for c in mv["claim_results"]])
        if m.get("reasons"):
            print("   reasons:", m["reasons"])
        text = mv.get("text") or mv.get("body") or ""
        print("   text:", text if full else text[:700].replace("\n", " | "))
        for t in bo.get((m["round"], m["actor"]), []):
            print("   BO:", t[:400])

